-- v2 of orders: exercises every ALTER path the diff engine now generates.
--   sequences:   ALTER SEQUENCE (cache), DROP SEQUENCE (legacy_seq)
--   identity:    SET GENERATED BY DEFAULT
--   columns:     DROP COLUMN note, SET DEFAULT status, DROP NOT NULL status,
--                DROP EXPRESSION total
--   constraints: FK action change (drop + ADD NOT VALID + VALIDATE),
--                CHECK replaced, UNIQUE added via CREATE UNIQUE INDEX ASYNC + USING INDEX
--   indexes:     partial predicate changed (replace), expression index dropped
--   statistics:  replaced kinds, new statistics object

CREATE SEQUENCE order_number_seq CACHE 1;

CREATE TABLE orders (
    id         BIGINT GENERATED BY DEFAULT AS IDENTITY (CACHE 65536) PRIMARY KEY,
    number     BIGINT NOT NULL DEFAULT nextval('order_number_seq'),
    user_id    TEXT NOT NULL REFERENCES users (id) ON DELETE RESTRICT,
    status     TEXT DEFAULT 'pending',
    qty        INTEGER NOT NULL,
    unit_price NUMERIC(10,2) NOT NULL,
    total      NUMERIC(12,2),
    metadata   JSONB,
    CONSTRAINT orders_qty_range CHECK (qty < 1000),
    CONSTRAINT orders_user_number_key UNIQUE (user_id, number)
);

CREATE INDEX ASYNC idx_orders_user ON orders (user_id);
CREATE INDEX ASYNC idx_orders_open ON orders (user_id, status) WHERE status IN ('open', 'pending');
CREATE UNIQUE INDEX ASYNC idx_orders_number ON orders (number) NULLS NOT DISTINCT;

CREATE STATISTICS orders_user_status (mcv) ON user_id, status FROM orders;
CREATE STATISTICS orders_qty_price ON qty, unit_price FROM orders;

-- New table created after an existing one it references.
CREATE TABLE order_items (
    order_id BIGINT NOT NULL,
    line_no  INTEGER NOT NULL,
    sku      TEXT NOT NULL,
    PRIMARY KEY (order_id, line_no),
    CONSTRAINT order_items_order_fk FOREIGN KEY (order_id) REFERENCES orders (id) ON DELETE CASCADE
);
